INSERT INTO `v1_9f7752631000ec6634611e370f7216bacf7e2f6514d10ee01840b8f022a24718` VALUES (92435330, 18, "ダメージ減衰", "すべてのモンスターが一度の行動で受けるダメージ値を減衰させる。ダメージ値が上昇するほど減衰率も上昇する。", 2947);
INSERT INTO `v1_9f7752631000ec6634611e370f7216bacf7e2f6514d10ee01840b8f022a24718` VALUES (92435330, 17, "ＴＰ上昇上限付与", "バトル開始時、すべてのキャラのＴＰ上昇の上限値を150にする。", 2948);
INSERT INTO `v1_9f7752631000ec6634611e370f7216bacf7e2f6514d10ee01840b8f022a24718` VALUES (92435330, 9, "ＨＰ吸収ダウン", "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", 2949);
