INSERT INTO `v1_9f7752631000ec6634611e370f7216bacf7e2f6514d10ee01840b8f022a24718` VALUES (92435340, 15, "光属性ボーナス特大アップ", "光属性のキャラが４体以上編成されているとき、キャラの属性ボーナスが強化される。光属性以外の属性ボーナスを無効化する。", 2951);
